package cl.robermotos.order;
import cl.robermotos.delivery.dto.DeliveryRequest; import org.springframework.stereotype.Component; import java.util.concurrent.*;
@Component public class OrderStore { public static class O {public String provider,quoteId;public DeliveryRequest request;public boolean paid;} private final ConcurrentMap<String,O> data=new ConcurrentHashMap<>();private final ConcurrentMap<String,String> tokens=new ConcurrentHashMap<>(); public void save(String id,String p,String q,DeliveryRequest r){O o=new O();o.provider=p;o.quoteId=q;o.request=r;data.put(id,o);} public void token(String t,String id){tokens.put(t,id);}public String byToken(String t){return tokens.get(t);}public boolean paid(String id){return data.get(id).paid;}public void markPaid(String id){data.get(id).paid=true;}public O get(String id){return data.get(id);} }